diff --git a/src/pages/Totals.tsx b/src/pages/Totals.tsx
index 3c4d5e6..7f8a9b0 100644
--- a/src/pages/Totals.tsx
+++ b/src/pages/Totals.tsx
@@ -12,7 +12,8 @@ export function Totals({ expenses }: { expenses: Expense[] }) {
   const byMonth = groupBy(expenses, (e) => e.date.slice(0, 7));
   return (
     <table>
-      {Object.entries(byMonth).map(([month, list]) => <tr key={month}><td>{month}</td><td>{list.length}</td></tr>)}
+      {Object.entries(byMonth).sort(([a], [b]) => b.localeCompare(a)).map(([month, list]) => (
+        <tr key={month}><td>{month}</td><td>{formatMoney(list.reduce((sum, e) => sum + e.amount, 0))}</td></tr>))}
     </table>
   );
 }
