 });
+
+test("each month shows its sum, newest first", () => {
+  render(<Totals expenses={[{ date: "2026-10-02", amount: 5 }, { date: "2026-11-01", amount: 7 }, { date: "2026-11-03", amount: 3 }]} />);
+  const rows = screen.getAllByRole("row");
+  expect(rows[0]).toHaveTextContent("2026-11");
+  expect(rows[0]).toHaveTextContent("10.00");
+});
